        'context': {
            'client': {
                'clientName': 'WEB',
                'clientVersion': '2.20240101.00.00',
                'hl': 'en',
                'gl': 'US'
            }
        },
        'browseId': 'UCX6OQ3DkcsbYNE6H8uQQuVA'
    }

    response = requests.post(url, json=data, headers=headers)
    if response.status_code != 200:
        print(f'Error: {response.status_code}')
        return []

