    # Navigate to the video tab and get continuation token
    tabs = browse_data.get('contents', {}).get('twoColumnBrowseResultsRenderer', {}).get('tabs', [])
    video_tab = None
    for tab in tabs:
        tab_renderer = tab.get('tabRenderer', {})
        if tab_renderer.get('title') == 'Videos':
            video_tab = tab
            break

    if not video_tab:
        # Try another approach - look for continuation
        content = browse_data.get('contents', {})
        if 'singleColumnBrowseResultsRenderer' in content:
            tab_list = content['singleColumnBrowseResultsRenderer'].get('tabs', [])
            for tab in tab_list:
                tab_renderer = tab.get('tabRenderer', {})
                if tab_renderer.get('title') == 'Videos':
                    video_tab = tab
                    break

    if not video_tab:
        print('No video tab found')
        return []

    # Get section list and first item
    section_list = video_tab.get('tabRenderer', {}).get('content', {}).get('richGridRenderer', {}).get('contents', [])

    if not section_list:
        # Try different structure
        for key, val in video_tab.get('tabRenderer', {}).get('content', {}).items():
            section_list = val.get('richGridRenderer', {}).get('contents', [])
            if section_list:
                break

    if not section_list:
