                    'upload_date': v.get('publishedTimeText', {}).get('simpleText', ''),
                })

    # Check for continuation token
    for item in section_list:
        if 'continuationItemRenderer' in item:
            continuation_token = item['continuationItemRenderer']['continuationEndpoint']['continuationCommand']['token']
            break

    print(f'First page: {len(videos)} videos')
    print(f'Continuation: {continuation_token[:20] if continuation_token else "None"}')

