            'context': {
                'client': {
                    'clientName': 'WEB',
                    'clientVersion': '2.20240101.00.00',
                }
            },
            'continuation': continuation_token
        }

        resp2 = requests.post(url, json=data2, headers=headers)
        if resp2.status_code != 200:
            print(f'Continuation error: {resp2.status_code}')
            break

        data2 = resp2.json()
        contents = data2.get('onResponseReceivedActions', [{}])[0].get('appendContinuationItemsAction', {}).get('continuationItems', [])

