import json
import requests
import time

def fetch_all_videos():
    url = 'https://www.youtube.com/youtubei/v1/browse'
    headers = {'Content-Type': 'application/json'}

    data = {
        'context': {
            'client': {
                'clientName': 'WEB',
                'clientVersion': '2.20240101.00.00'
            }
        },
        'browseId': 'UCX6OQ3DkcsbYNE6H8uQQuVA'
    }

    resp = requests.post(url, json=data, headers=headers)
    d = resp.json()

    # Navigate to video tab
    two_col = d['contents']['twoColumnBrowseResultsRenderer']
    tabs = two_col['tabs']

    video_tab = None
    for tab in tabs:
        if 'tabRenderer' in tab:
            if tab['tabRenderer'].get('title') == 'Videos':
                video_tab = tab['tabRenderer']
                break

    if not video_tab:
        print('No Videos tab found')
        # Print available tabs
        for tab in tabs:
            print(f'  Tab: {tab}')
        return []

    # Get richGridRenderer contents
    content = video_tab.get('content', {})
    rich_grid = content.get('richGridRenderer', {})
    sections = rich_grid.get('contents', [])

    if not sections:
        # Try alternative structure
        print(f'Content keys: {list(content.keys())}')
        for k, v in content.items():
            if isinstance(v, dict):
                print(f'  {k} keys: {list(v.keys())[:5]}')
        return []

    videos = []
    continuation_token = None

    def process_items(items):
        nonlocal continuation_token
        for item in items:
            if 'richItemRenderer' in item:
                video = item['richItemRenderer']['content']
                vid = None
                if 'videoRenderer' in video:
                    vid = video['videoRenderer']
                elif 'videoWithContextRenderer' in video:
                    vid = video['videoWithContextRenderer']

                if vid:
                    vid_id = vid.get('videoId', '')
                    title = ''
                    if 'title' in vid:
                        runs = vid['title'].get('runs', [])
                        if runs:
                            title = runs[0].get('text', '')

                    duration = 0
                    length_s = vid.get('lengthSeconds', '0')
                    try:
                        duration = int(length_s)
                    except:
                        pass

                    videos.append({
                        'id': vid_id,
                        'title': title,
                        'duration': duration,
                        'upload_date': ''
                    })

            if 'continuationItemRenderer' in item:
                ce = item['continuationItemRenderer'].get('continuationEndpoint', {})
                if ce and 'continuationCommand' in ce:
                    continuation_token = ce['continuationCommand'].get('token')
                return  # Only one continuation per batch

    # First page
    process_items(sections)
    print(f'Page 1: {len(videos)} videos')
    print(f'First video: {videos[0] if videos else "none"}')

    # Pagination
    max_pages = 50
    for page in range(max_pages):
        if not continuation_token:
            print('No more continuation')
            break

        data2 = {
            'context': {'client': {'clientName': 'WEB', 'clientVersion': '2.20240101.00.00'}},
            'continuation': continuation_token
        }

        resp2 = requests.post(url, json=data2, headers=headers)
        d2 = resp2.json()

        actions = d2.get('onResponseReceivedActions', [])
        for action in actions:
            append = action.get('appendContinuationItemsAction', {})
            items = append.get('continuationItems', [])
            if items:
                process_items(items)
                break
        else:
            print(f'No continuation items in page {page+2}')
            break

        print(f'  Page {page+2}: {len(videos)} total')
        time.sleep(1)

    return videos

